A;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA,8BAA8B;AAC9B,qBAAqB;AACrB;AACA;AACA;AACA,gCAAgC;AAChC,uBAAuB;AACvB;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA,uBAAuB,oCAAoC;AAC3D,kBAAkB,uBAAuB;AACzC;AACA;AACA;AACA;AACA;;;;;;;;;;;;;;AClMA;AAAA;AAAA;AAAA;AACA;AACA;AACA;AACA;AACA,iBAAiB,uBAAuB;AACxC,mBAAmB,uCAAuC;AAC1D;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA,oBAAoB;AACpB,WAAW;AACX;AACA;AACA;AACA,sBAAsB;AACtB,aAAa;AACb,WAAW;AACX;AACA;AACA;AACA;AACA;AACA;AACA;;;;;;;;;;;;;;AC/BA;AAAA;AAAA;AAAA;AACA;AACA;AACA;AACA;AACA,gBAAgB,yBAAyB;AACzC;AACA;AACA,SAAS,SAAS,uBAAuB,EAAE;AAC3C;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA,iBAAiB;AACjB;AACA;AACA;AACA,4BAA4B;AAC5B,mBAAmB;AACnB;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;;;;;;;;;;;;;;AC9EA;AAAA;AAAA;AAAA;AAAqG;AAC3B;AACL;;;AAGrE;AACsG;AACtG,gBAAgB,2GAAU;AAC1B,EAAE,4FAAM;AACR,EAAE,iGAAM;AACR,EAAE,0GAAe;AACjB;AACA;AACA;AACA;;AAEA;;AAEA;AACA,IAAI,KAAU,EAAE,YAiBf;AACD;AACe,gF;;;;;;;;;;;;ACtCf;AAAA;AAAA,wCAA8M,CAAgB,0PAAG,EAAC,C;;;;;;;;;;;;ACAlO;AAAA;AAAA;AAAA;AAAA;AAAA;;;;;;;;;;;;;ACAA;AAAA;AAAA;AAAA;AAAqG;AAC3B;AACL;;;AAGrE;AACsG;AACtG,gBAAgB,2GAAU;AAC1B,EAAE,4FAAM;AACR,EAAE,iGAAM;AACR,EAAE,0GAAe;AACjB;AACA;AACA;AACA;;AAEA;;AAEA;AACA,IAAI,KAAU,EAAE,YAiBf;AACD;AACe,gF;;;;;;;;;;;;ACtCf;AAAA;AAAA,wCAA8M,CAAgB,0PAAG,EAAC,C;;;;;;;;;;;;ACAlO;AAAA;AAAA;AAAA;AAAA;AAAA;;;;;;;;;;;;;ACAA;AAAA;AAAA;AAAA;AAAyG;AAC3B;AACL;;;AAGzE;AACsG;AACtG,gBAAgB,2GAAU;AAC1B,EAAE,gGAAM;AACR,EAAE,qGAAM;AACR,EAAE,8GAAe;AACjB;AACA;AACA;AACA;;AAEA;;AAEA;AACA,IAAI,KAAU,EAAE,YAiBf;AACD;AACe,gF;;;;;;;;;;;;ACtCf;AAAA;AAAA,wCAAkN,CAAgB,8PAAG,EAAC,C;;;;;;;;;;;;ACAtO;AAAA;AAAA;AAAA;AAAA;AAAA","file":"chunks/ceres-client-6.js","sourcesContent":["<template>\n    <div id=\"add-item-to-basket-overlay\">\n        <div class=\"modal fade\">\n            <div class=\"modal-dialog\" role=\"document\">\n                <div class=\"modal-content\" v-if=\"basketItem\">\n\n                    <!-- MODAL HEADER -->\n                    <div class=\"modal-header\">\n                        <div class=\"modal-title h5\">{{ $translate(\"Ceres::Template.singleItemAdded\") }}</div>\n                        <span class=\"text-muted ml-auto\"><span class=\"timer\"></span>s</span>\n                        <button type=\"button\" class=\"close ml-0 pl-1\" data-dismiss=\"modal\" :aria-label=\"$translate('Ceres::Template.closeIcon')\">\n                            <span aria-hidden=\"true\">&times;</span>\n                        </button>\n                    </div>\n                    <!-- ./MODAL HEADER -->\n\n                    <!-- MODAL BODY -->\n                    <div class=\"modal-body\">\n                        <div class=\"row is-table-row\">\n                            <div class=\"col-md-4\" style=\"min-height: 80px;\">\n                                <img style=\"max-height: 140px;\" class=\"img-fluid mx-auto\" :src=\"imageUrl\" :alt=\"imageAlternativeText || itemName\" :title=\"itemName\"/>\n                            </div>\n                            <div class=\"col-md-8\">\n                                <p>\n                                    <strong>{{ itemName }}</strong>\n                                    <br>\n                                    <span v-if=\"countAdditionalBasketItems > 0\">{{ $translate(\"Ceres::Template.basketItemOverlayAdditionalCount\", {\"count\": countAdditionalBasketItems }) }}</span>\n                                </p>\n\n                                <p class=\"small\">\n                                    <strong>\n                                        <span class=\"text-muted\">{{ basketItem.quantity }} x </span>\n                                        <span>{{ price | currency }}</span>\n                                    </strong>\n                                </p>\n                                <!--<p>\n                                    <item-bundle v-if=\"isLastBasketEntrySet\" :bundle-type=\"variation.variation.bundleType\" :bundle-components=\"variation.bundleComponents\"></item-bundle>\n                                </p> -->\n\n                                <p class=\"small\" v-for=\"attribute in variation.attributes\">\n                                    <strong>{{ attribute.attribute.names.name }}</strong>:\n                                    <span>{{ attribute.value.names.name }}</span>\n                                </p>\n\n                                <order-property-value-list :basket-item=\"basketItem\"></order-property-value-list>\n\n                            </div>\n                        </div>\n                    </div>\n                    <!-- ./MODAL BODY -->\n\n                    <!-- MODAL FOOTER -->\n                    <div class=\"modal-footer\">\n                        <a v-waiting-animation-infinite :href=\"urls.basket\" rel=\"nofollow\" class=\"btn btn-outline-primary btn-medium mr-2\">\n                            <i class=\"fa fa-shopping-cart\" aria-hidden=\"true\"></i>\n                            {{ $translate(\"Ceres::Template.singleItemBasket\") }}\n                        </a>\n                        <a v-waiting-animation-infinite :href=\"urls.checkout\" rel=\"nofollow\" class=\"btn btn-primary btn-medium\">\n                            <i class=\"fa fa-arrow-right\" aria-hidden=\"true\"></i>\n                            {{ $translate(\"Ceres::Template.singleItemCheckout\") }}\n                        </a>\n                    </div>\n                    <slot name=\"extendOverlayButtons\"></slot>\n                    <!-- ./MODAL FOOTER -->\n\n                </div>\n            </div>\n        </div>\n    </div>\n</template>\n\n<script>\nimport { isNullOrUndefined } from \"../../helper/utils\";\nimport { mapState } from \"vuex\";\nimport OrderPropertyValueList from \"../item/OrderPropertyValueList.vue\"\n\nconst ModalService  = require(\"../../services/ModalService\");\nconst ApiService    = require(\"../../services/ApiService\");\n\nexport default {\n    name: \"add-item-to-basket-overlay\",\n\n    components: {\n        OrderPropertyValueList\n    },\n    \n    props: {\n        defaultTimeToClose: {\n            type: Number,\n            default: 15\n        }\n    },\n\n    data()\n    {\n        return {\n            price: 0,\n            basketItem: null,\n            countAdditionalBasketItems: 0\n        };\n    },\n\n    mounted()\n    {\n        if (App.config.basket.addItemToBasketConfirm === \"overlay\")\n        {\n            ApiService.listen(\"AfterBasketItemUpdate\", data =>\n            {\n                const updatedBasketItem = data.basketItems[0];\n\n                if (!this.isBasketItemQuantityUpdate)\n                {\n                    const basketItem = this.basketItems.find(item => item.id === updatedBasketItem.id) || {};\n\n                    this.showItem(basketItem);\n                }\n            });\n\n            ApiService.listen(\"AfterBasketItemAdd\", data =>\n            {\n                this.showItem(data.basketItems[0], data.basketItems.length - 1);\n            });\n        }\n    },\n\n    computed:\n    {\n        ...mapState({\n            basketItems: state => state.basket.items,\n            isBasketItemQuantityUpdate: state => state.basket.isBasketItemQuantityUpdate\n        }),\n\n        isLastBasketEntrySet()\n        {\n            return !isNullOrUndefined(this.basketItem);\n        },\n\n        variation()\n        {\n            if (this.basketItem)\n            {\n                return this.basketItem.variation ? this.basketItem.variation.data : null;\n            }\n\n            return null;\n        },\n\n        itemName()\n        {\n            if (this.isLastBasketEntrySet)\n            {\n                return this.$options.filters.itemName(this.variation);\n            }\n\n            return \"\";\n        },\n\n        imageUrl()\n        {\n            if (this.isLastBasketEntrySet)\n            {\n                const images = this.$options.filters.itemImages(this.variation.images, \"urlPreview\");\n\n                return this.$options.filters.itemImage(images);\n            }\n\n            return \"\";\n        },\n\n        imageAlternativeText()\n        {\n            if (this.isLastBasketEntrySet)\n            {\n                const images = this.$options.filters.itemImages(this.variation.images, \"urlPreview\");\n\n                return this.$options.filters.itemImageAlternativeText(images);\n            }\n\n            return \"\";\n        },\n\n        urls()\n        {\n            return {\n                basket: App.urls.basket,\n                checkout: App.urls.checkout\n            }\n        }\n    },\n\n    methods:\n    {\n        showItem(basketItem, countAdditionalBasketItems)\n        {\n            this.basketItem = basketItem;\n            this.countAdditionalBasketItems = countAdditionalBasketItems;\n            this.price = basketItem.price;\n\n            ModalService\n                .findModal(document.getElementById(\"add-item-to-basket-overlay\"))\n                .setTimeout(this.defaultTimeToClose * 1000)\n                .show();\n        }\n    }\n}\n</script>\n","<template>\n    <div class=\"small\" v-if=\"shownProperties && shownProperties.length\">\n        <div class=\"font-weight-bold my-1\">{{ $translate('Ceres::Template.basketAdditionalCosts') }}:</div>\n        <ul class=\"ml-1 pl-3\" data-testing=\"order-property-list\">\n            <order-property-value-list-item v-for=\"property in shownProperties\" :key=\"property.propertyId\" :property=\"property\"></order-property-value-list-item>\n        </ul>\n    </div>\n</template>\n\n<script>\nimport { isDefined } from '../../helper/utils';\nimport OrderPropertyValueListItem from './OrderPropertyValueListItem.vue';\n\nexport default {\n    name: \"order-property-value-list\",\n\n    components:\n    {\n        OrderPropertyValueListItem\n    },\n\n    props:\n    {\n        basketItem:\n        {\n            required: true,\n            type: Object\n        }\n    },\n\n    computed:\n    {\n        shownProperties()\n        {\n            const shownProperties = [];\n\n            this.basketItem.variation.data.properties.forEach(property =>\n            {\n                const filledProperty = this.basketItem.basketItemOrderParams.find(prop =>\n                {\n                    return parseInt(prop.propertyId) === property.propertyId;\n                });\n\n                if (isDefined(filledProperty))\n                {\n                    if (filledProperty.type === \"selection\")\n                    {\n                        property.property.value = property.property.selectionValues[filledProperty.value].name;\n                    }\n                    else\n                    {\n                        property.property.value = filledProperty.value;\n                    }\n                }\n\n                if(isDefined(filledProperty) || this.isPropertyWithAdditionalCosts(property))\n                {\n                    shownProperties.push(property);\n                }\n            });\n\n            return shownProperties;\n        }\n    },\n\n    methods:\n    {\n        isPropertyWithAdditionalCosts(property)\n        {\n            return property.property &&\n                property.property.isShownAtCheckout &&\n                property.property.isShownAsAdditionalCosts &&\n                !property.property.isOderProperty\n        }\n    }\n}\n</script>\n","<template>\n    <li>\n        <span class=\"d-block\">\n            <strong :class=\"{ 'colon': showColon }\">\n                {{ property.property.names.name }} \n                <template v-if=\"surcharge > 0\">\n                    <template v-if=\"isAdditionalCost || isTaxless\">\n                        ({{ $translate(\"Ceres::Template.basketPlusAbbr\") }} {{ surcharge | currency }})\n                    </template>\n                    <template v-else>\n                        ({{ $translate(\"Ceres::Template.basketIncludeAbbr\") }} {{ surcharge | currency }})\n                    </template>\n                </template>\n            </strong>\n            <span>\n                <span v-if=\"property.property.valueType === 'file'\">\n                    <a :href=\"property.property.value | fileUploadPath\" target=\"_blank\">\n                        <i class=\"fa fa-external-link\" aria-hidden=\"true\"></i>\n                        {{ property.property.value | fileName }}\n                    </a>\n                </span>\n                <span v-else-if=\"property.property.valueType !== 'empty'\">{{ property.property.value }}</span>\n            </span>\n        </span>\n    </li>\n</template>\n\n<script>\nimport { hasVat, isAdditionalCosts } from \"../../helper/OrderPropertyHelper\";\nexport default {\n    name: \"order-property-value-list-item\",\n\n    props:\n    {\n        property:\n        {\n            required: true,\n            type: Object\n        }\n    },\n\n    computed:\n    {\n        surcharge()\n        {\n            return this.$options.filters.propertySurcharge([this.property], this.property.propertyId);\n        },\n\n        isAdditionalCost()\n        {\n            return isAdditionalCosts(this.property);\n        },\n\n        isTaxless()\n        {\n            return !hasVat(this.property) && App.useVariationOrderProperties;\n        },\n\n        showColon()\n        {\n            return this.property && this.property.property.value && this.property.property.valueType !== \"empty\";\n        }\n    }\n}\n</script>\n","var render = function() {\n  var _vm = this\n  var _h = _vm.$createElement\n  var _c = _vm._self._c || _h\n  return _c(\"div\", { attrs: { id: \"add-item-to-basket-overlay\" } }, [\n    _c(\"div\", { staticClass: \"modal fade\" }, [\n      _c(\"div\", { staticClass: \"modal-dialog\", attrs: { role: \"document\" } }, [\n        _vm.basketItem\n          ? _c(\n              \"div\",\n              { staticClass: \"modal-content\" },\n              [\n                _c(\"div\", { staticClass: \"modal-header\" }, [\n                  _c(\"div\", { staticClass: \"modal-title h5\" }, [\n                    _vm._v(\n                      _vm._s(_vm.$translate(\"Ceres::Template.singleItemAdded\"))\n                    )\n                  ]),\n                  _vm._v(\" \"),\n                  _vm._m(0),\n                  _vm._v(\" \"),\n                  _c(\n                    \"button\",\n                    {\n                      staticClass: \"close ml-0 pl-1\",\n                      attrs: {\n                        type: \"button\",\n                        \"data-dismiss\": \"modal\",\n                        \"aria-label\": _vm.$translate(\n                          \"Ceres::Template.closeIcon\"\n                        )\n                      }\n                    },\n                    [\n                      _c(\"span\", { attrs: { \"aria-hidden\": \"true\" } }, [\n                        _vm._v(\"×\")\n                      ])\n                    ]\n                  )\n                ]),\n                _vm._v(\" \"),\n                _c(\"div\", { staticClass: \"modal-body\" }, [\n                  _c(\"div\", { staticClass: \"row is-table-row\" }, [\n                    _c(\n                      \"div\",\n                      {\n                        staticClass: \"col-md-4\",\n                        staticStyle: { \"min-height\": \"80px\" }\n                      },\n                      [\n                        _c(\"img\", {\n                          staticClass: \"img-